const RSA_PRIVATE_KEY = ''

// 响应解密：当响应头 x-encrypt 为 true 时，先用平台 RSA 私钥解出 AES 密钥，
// 再用 AES-CBC/PKCS7（固定全 0 IV）解密 res.data.data，并将 res.data 替换为解析后的 JSON
function decryptResponseData(res) {
  const headers = res.headers || {}
  if (headers['x-encrypt'] == 'true' && res.data && res.data.key && res.data.data) {
    try {
      const decryptor = new JSEncrypt()
      decryptor.setPrivateKey(RSA_PRIVATE_KEY)
      const aesKeyBase64 = decryptor.decrypt(res.data.key)
      if (!aesKeyBase64) {
        console.error('响应解密失败：RSA 解密 AES 密钥为空')
        return
      }
      const aesKey = CryptoJS.enc.Base64.parse(aesKeyBase64)
      const iv = CryptoJS.enc.Hex.parse('00000000000000000000000000000000')
      const decrypted = CryptoJS.AES.decrypt(res.data.data, aesKey, {
        iv: iv,
        mode: CryptoJS.mode.CBC,
        padding: CryptoJS.pad.Pkcs7
      })
      const decryptedText = decrypted.toString(CryptoJS.enc.Utf8)
      res.data = JSON.parse(decryptedText)
    } catch (e) {
      console.error('响应解密异常，保留原始响应：', e)
    }
  }
}

