import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import CryptoJS from 'crypto-js'
import JSEncrypt from 'jsencrypt'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const src = fs.readFileSync(path.resolve(__dirname, 'src/request/index.js'), 'utf8')
const m = src.match(/RSA_PRIVATE_KEY = '([^']+)'/)
if (!m) { console.error('RSA key not found in src/request/index.js'); process.exit(1) }
const key = m[1]

// 1) JSEncrypt 必须能解析平台 RSA 私钥（不抛错说明格式有效、库可加载）
const d = new JSEncrypt()
d.setPrivateKey(key)
console.log('[1] JSEncrypt setPrivateKey ok, key length =', key.length)

// 2) crypto-js 的 AES/CBC/Pkcs7 必须可用（拦截器依赖）
console.log('[2] crypto-js available:',
  'AES=', typeof CryptoJS.AES,
  'CBC=', typeof CryptoJS.mode.CBC,
  'Pkcs7=', typeof CryptoJS.pad.Pkcs7)

// 3) 与拦截器一致的配置：AES-CBC / PKCS7 / 全 0 IV 做一次加解密往返
const aesKey = CryptoJS.enc.Utf8.parse('1234567890abcdef')
const iv = CryptoJS.enc.Hex.parse('00000000000000000000000000000000')
const ct = CryptoJS.AES.encrypt('hello 昆山市民', aesKey, { iv, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7 })
const pt = CryptoJS.AES.decrypt(ct, aesKey, { iv, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7 }).toString(CryptoJS.enc.Utf8)
console.log('[3] AES-CBC/PKCS7 round-trip:', pt === 'hello 昆山市民' ? 'OK' : 'FAIL (' + pt + ')')

// jsencrypt 在模块加载时会访问 window.crypto（及可能的 navigator / self），
// 而 uni-app 小程序端（MP-WEIXIN）与 Node 环境没有 window 全局对象，
// 直接 import jsencrypt 会抛 "ReferenceError: window is not defined"，
// 导致整个 request 模块加载失败、应用无法发请求。
// 这里在 import jsencrypt 之前补齐最小全局垫片：仅当 window 不存在时生效，
// H5 端已有 window，垫片不执行，不影响原行为。
if (typeof globalThis.window === 'undefined') {
  // @ts-ignore
  globalThis.window = globalThis
  if (typeof globalThis.navigator === 'undefined') {
    globalThis.navigator = { appName: 'Netscape', userAgent: 'uni-app' }
  }
  if (typeof globalThis.self === 'undefined') {
    globalThis.self = globalThis
  }
}

export default {}

